// Open-Meteo: free, no key. The sunset time plus cloud, wind and rain in the sunset hour.
const S = $('Romeo settings').first().json;
const f = $input.first().json;
const sunsetAt = f.daily.sunset[0];                      // local time, e.g. 2026-11-06T19:05
const i = Math.max(0, f.hourly.time.indexOf(sunsetAt.slice(0, 13) + ':00'));
const cloud = f.hourly.cloud_cover[i];
const wind = Math.round(f.hourly.wind_speed_10m[i]);
const rain = f.hourly.precipitation_probability[i];
const sunset = sunsetAt.slice(11, 16);
const checks = {
  'clear skies': cloud <= S.RULES.maxCloud,
  'no wind': wind <= S.RULES.maxWindKmh,
  'no rain': rain <= S.RULES.maxRain,
  'sunset after seven': sunset >= S.RULES.sunsetAfter,
};
const perfect = Object.values(checks).every(Boolean);
const day = new Date(sunsetAt + ':00').toLocaleDateString('en-AU', { weekday: 'long', day: 'numeric', month: 'short' });
return [{ json: { date: sunsetAt.slice(0, 10), day, sunset, cloud, wind, rain, checks, perfect,
  forced: !perfect && !!S.FORCE_GO } }];

// FILMING: both calendars, same shape as two Google Calendar "availability" checks.
// The full build asks Google for real.
return [{ json: { me: { available: true }, her: { available: true } } }];

const S = $('Romeo settings').first().json;
const sky = $('Read the sky').first().json;
const cal = $input.first().json;
const bothFree = !!(cal.me && cal.me.available && cal.her && cal.her.available);
const go = (sky.perfect || sky.forced) && bothFree;
const tick = (ok) => (ok ? '✅' : '❌');
const lines = Object.entries(sky.checks).map(([k, v]) => `${tick(v)} ${k}`);
lines.push(`${tick(bothFree)} both free after six`);
return [{ json: { go, bothFree, report: `🌅 <b>Sunset ${sky.sunset}</b>, ${sky.cloud}% cloud, ${sky.wind} km/h wind\n` + lines.join('\n') +
  (sky.forced ? '\n<i>(filming: sky forced perfect)</i>' : '') } }];

// FILMING: the restaurants she's saved or sent you on Instagram. Instagram has no API for
// saved posts, so in the full build she (or you) forwards them to Romeo on Telegram and
// he files them. Same shape as a Google Places lookup of each one.
return [
  { name: 'Odyssea',            suburb: 'City Beach',  cuisine: 'Seafood',        lat: -31.9389, lng: 115.7546, ig: 'https://www.instagram.com/p/odyssea/',     about: 'Beachfront dining room, floor-to-ceiling windows straight onto the Indian Ocean.' },
  { name: 'Si Paradiso',        suburb: 'Highgate',    cuisine: 'Italian',        lat: -31.9395, lng: 115.8706, ig: 'https://www.instagram.com/p/siparadiso/',  about: 'Moody courtyard bar and pasta. No view.' },
  { name: 'The Shorehouse',     suburb: 'Swanbourne',  cuisine: 'Modern Aussie',  lat: -31.9706, lng: 115.7556, ig: 'https://www.instagram.com/p/shorehouse/',  about: 'On the dunes at Swanbourne beach, west-facing deck and window tables.' },
  { name: 'Lulu La Delizia',    suburb: 'Subiaco',     cuisine: 'Pasta',          lat: -31.9469, lng: 115.8264, ig: 'https://www.instagram.com/p/lululadelizia/', about: 'Tiny handmade pasta spot. Street-facing, no view.' },
  { name: 'Bib & Tucker',       suburb: 'Leighton',    cuisine: 'Mediterranean',  lat: -32.0262, lng: 115.7509, ig: 'https://www.instagram.com/p/bibandtucker/', about: 'Leighton Beach, looks west over the water.' },
  { name: 'Long Chim',          suburb: 'Perth CBD',   cuisine: 'Thai',           lat: -31.9558, lng: 115.8596, ig: 'https://www.instagram.com/p/longchim/',    about: 'Basement in the State Buildings. Loud, fun, no windows.' },
].map(j => ({ json: j }));

// Hand Romeo every saved spot and tonight's sunset, and ask for ONE pick back as JSON.
const S = $('Romeo settings').first().json;
const sky = $('Read the sky').first().json;
const saves = $input.all().map((i, n) => ({ n, ...i.json }));
const prompt = `You plan date night. Tonight's sunset is at ${sky.sunset} in ${S.TIMEZONE}.
Below are restaurants she has saved. Pick the ONE most likely to have a table for two by a window looking straight at the sunset (west-facing, on the water beats everything).
Never pick a place with no view.
Reply with JSON only: {"n": <number>, "why": "<one short sentence>", "dressCode": "<2-5 words>", "vibe": "<3-6 words>"}

${saves.map(s => `${s.n}. ${s.name} (${s.suburb}) - ${s.cuisine}. ${s.about || ''}`).join('\n')}`;
return [{ json: { saves, body: { model: S.MODEL, max_tokens: 300, messages: [{ role: 'user', content: prompt }] } } }];

// Claude's pick, checked. If Claude is off (ZERO_SPEND) or answers badly, take the first
// spot that mentions water, so the run never stalls.
const S = $('Romeo settings').first().json;
const sky = $('Read the sky').first().json;
const saves = $('Brief for Romeo').first().json.saves;
let pick = {};
try {
  const txt = ($input.first().json.content || [])[0].text;
  pick = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1));
} catch (e) { pick = {}; }
let r = saves[pick.n];
if (!r) {
  r = saves.find(s => /water|ocean|beach|west/i.test(s.about || '')) || saves[0];
  pick = { why: 'Right on the water, facing west.', dressCode: 'Smart casual', vibe: 'Sunset by the water' };
}
// book 30 minutes before sunset, on a quarter hour
const [h, m] = sky.sunset.split(':').map(Number);
let mins = h * 60 + m - 30; mins -= mins % 15;
const time = `${String(Math.floor(mins / 60)).padStart(2, '0')}:${String(mins % 60).padStart(2, '0')}`;
const nice = new Date(`${sky.date}T${time}:00`).toLocaleTimeString('en-AU', { hour: 'numeric', minute: '2-digit' });
return [{ json: { ...r, why: pick.why, dressCode: pick.dressCode || 'Smart casual', vibe: pick.vibe || '',
  date: sky.date, day: sky.day, time, niceTime: nice, sunset: sky.sunset, party: S.PARTY } }];

// FILMING: the browser agent checking the restaurant's booking page for a window table.
// Same shape the full build's agent returns. Nothing is booked until she says yes.
const r = $input.first().json;
return [{ json: { ...r, available: true, table: 'Window, table for two', heldUntil: '2 hours' } }];

// Everything except the restaurant's name. That's staying a surprise.
const S = $('Romeo settings').first().json;
const r = $input.first().json;
const msg = `🌅 <b>Hey ${S.HER}, you've been asked on a date.</b>

📅 ${r.day}
🕰️ ${r.niceTime}, sunset's at ${r.sunset}
📍 ${r.suburb}
🍽️ ${r.cuisine}
👗 ${r.dressCode}
🤫 Where? That's staying a surprise.

You've got one choice:`;
return [{ json: { ...r, invite: msg } }];

// FILMING: the browser agent booking the table it held. Same shape as the real run.
const r = $('Write the invite').first().json;
return [{ json: { ...r, booked: true, ref: 'RM-' + String(Date.now()).slice(-5),
  notes: 'Window table for two for the sunset please. It is a date: could dessert come out with a candle in it? Thank you!' } }];

// The closest florist to her work, from OpenStreetMap (Nominatim: free, no key). A shop
// that lists an email gets the order; otherwise your usual florist does.
const S = $('Romeo settings').first().json;
const w = S.HER_WORK;
const shops = $input.all().map(i => i.json).filter(s => s && s.lat);   // n8n splits the result list into items
const km = (a, b, c, d) => { const R = 6371, r = Math.PI / 180;
  const x = Math.sin((c - a) * r / 2) ** 2 + Math.cos(a * r) * Math.cos(c * r) * Math.sin((d - b) * r / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(x)); };
const ranked = shops.map(s => ({ name: (s.name || s.display_name.split(',')[0]).trim(),
  email: (s.extratags || {}).email || (s.extratags || {})['contact:email'] || '',
  km: km(w.lat, w.lng, +s.lat, +s.lon) })).sort((a, b) => a.km - b.km);
// The order goes to the closest shop that lists an email, else your usual florist.
// Filming: the closest shop full stop, with the email landing in your own inbox.
const withEmail = ranked.find(s => s.email);
const florist = S.FILMING ? (ranked[0] || S.FALLBACK_FLORIST) : (withEmail || { ...S.FALLBACK_FLORIST, km: null });
const shop = florist.km != null ? florist : null;
const r = $('Book the table').first().json;
const to = S.FILMING ? S.MY_EMAIL : florist.email;
const html = `<p>Hi ${florist.name},</p>
<p>Could I please order a bunch of flowers (around $${S.FLOWERS.budget}) delivered <b>today by 3pm</b> to:</p>
<p><b>${w.address}</b></p>
<p>Card: <i>${S.FLOWERS.card}</i></p>
<p>Happy to pay by card over the phone or by link. Thank you!</p>
<p>${S.ME}</p>` + (S.FILMING ? `<hr><p style="color:#888">Filming: this landed in your inbox. In the full build it goes to ${florist.name}${shop ? ` (${shop.km.toFixed(1)} km from her work)` : ''} if they list an email, otherwise your usual florist.</p>` : '');
return [{ json: { to, subject: `Flower delivery today by 3pm - ${w.address}`, html, florist: florist.name,
  floristKm: shop ? Math.round(shop.km * 10) / 10 : null, booking: r } }];

// FILMING: the date blocked in both calendars. Same shape as a Google Calendar event.
const r = $('Book the table').first().json;
return [{ json: { id: 'romeo-' + r.date, summary: '🌅 Date night', start: { dateTime: `${r.date}T${r.time}:00` } } }];

const S = $('Romeo settings').first().json;
const r = $('Book the table').first().json;
const f = $('Order the flowers').first().json;
const sitterIn = $('Babysitter: can you do tonight?').first().json.data;
const ok = !sitterIn || sitterIn.approved !== false;
return [{ json: { msg: `🌹 <b>She said yes.</b> Romeo took it from there:

🍽️ <b>${r.name}</b>, ${r.niceTime}, ${r.table || 'window table'}. Booked (ref ${r.ref}).
👶 ${S.BABYSITTER.name}: ${ok ? 'confirmed' : "can't make it, sort a backup"}.
💐 Flowers from ${f.florist}${f.floristKm != null ? ` (${f.floristKm} km away)` : ''}, at her work by 3pm.
🕯️ Dessert comes out with a candle.
📅 In both calendars.

<i>Romeo's watching Find My for the drive home.</i>` } }];

// FILMING: Find My pings on the drive home, restaurant to front door. In the full build an
// iPhone Shortcut (or OwnTracks) posts your real location to Romeo's webhook.
const S = $('Romeo settings').first().json;
const r = $('Book the table').first().json;
return [0, 0.45, 0.7, 0.85].map((t, i) => ({ json: { ping: i + 1,
  lat: r.lat + (S.HOME.lat - r.lat) * t, lng: r.lng + (S.HOME.lng - r.lng) * t } }));

// OSRM drive time from each ping to home. The first one under ten minutes fires the finale.
const pings = $('Find My: the drive home').all().map(i => i.json);
const times = $input.all().map(i => Math.round(((i.json.routes || [])[0] || {}).duration || 9e9));
const hit = times.findIndex(t => t <= 600);
const i = hit < 0 ? times.length - 1 : hit;
return [{ json: { ...pings[i], minutesOut: Math.max(1, Math.round(times[i] / 60)), log: times.map((t, n) => `ping ${n + 1}: ${Math.round(t / 60)} min`).join(', ') } }];

// FILMING: paying the babysitter. Same shape as a funded Wise transfer.
const S = $('Romeo settings').first().json;
const r = $('Book the table').first().json;
const [h, m] = r.time.split(':').map(Number);
const hours = Math.max(3, Math.ceil((22 * 60 - (h * 60 + m - 30)) / 60));   // left 30 min before, home about 10pm
return [{ json: { status: 'outgoing_payment_sent', amount: hours * S.BABYSITTER.ratePerHour, hours } }];

// FILMING: Home Assistant turning the heater on. Same shape as its service call.
const S = $('Romeo settings').first().json;
return [{ json: { entity_id: S.HEATER, state: 'heat', attributes: { temperature: 22 } } }];

// FILMING: Spotify starting her song on the living-room speaker.
const S = $('Romeo settings').first().json;
return [{ json: { playing: true, track: `${S.HER_SONG.artist} - ${S.HER_SONG.title}` } }];

const S = $('Romeo settings').first().json;
const t = $('Ten minutes out?').first().json;
const p = $('Pay the babysitter').first().json;
return [{ json: { msg: `🏠 <b>${t.minutesOut} minutes from home.</b>

💸 ${S.BABYSITTER.name} paid $${p.amount}
🔥 Heater on, 22°
🎶 Playing: ${S.HER_SONG.artist ? S.HER_SONG.artist + ' - ' : ''}${S.HER_SONG.title}

Walk her through the door. 🌹` } }];
